"""Tests of check_tree.py: what looks like decompiler output, and that the repository has none.   python3 -m pytest tools/release"""
import os
import subprocess
import sys

import pytest

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(os.path.dirname(HERE))
sys.path.insert(0, HERE)

import check_tree  # noqa: E402

DECOMPILED = b"""/*
 * magic_all.c - Decompiled ANSI C Source for MAGIC.EXE
 * Generated by Ghidra Decompiler on 2026-08-25 08:38:56
 */
undefined4 UI_Register_00401000(HWND hwnd,uint y,undefined4 *param_1)
{
  int iVar1;
  undefined4 uVar2;
  iVar1 = FUN_00401c91(param_1);
  FUN_00401d23(iVar1);
  FUN_00401d2e(iVar1, 1);
  FUN_00401e65();
  FUN_00401f40(hwnd);
  return uVar2;
}
"""


def test_a_folder_named_like_the_removed_decompilation_is_refused():
    for path in ("magic/magic_all.c", "duel/duel_unified.c", "deckdll/x.csv", "scripts/ApplySymbolMap.java", "symbols/engine_globals_map.csv", "tools/ghidra/export.py", "docs/decompiled/a.md"):
        assert check_tree.problems_for_path(path), path


def test_a_file_named_like_a_decompiler_runs_output_is_refused():
    for path in ("function_index.csv", "duel/function_index.csv", "tools/x/symbols.csv", "src/magic_unified.c", "src/x/duel_all.c", "include/magic_unified.h"):
        assert check_tree.problems_for_path(path), path


def test_our_own_folders_and_names_are_fine():
    for path in ("src/port/main.c", "src/native/engine.h", "tools/lift/fnscan.py", "tools/registry/verified_names.csv", "docs/PHASE_C.md", "README.md", "src/port/all_main.c"):
        assert check_tree.problems_for_path(path) == [], path


def test_decompiled_source_is_recognised_by_its_header_calls_locals_and_types():
    found = check_tree.problems_for_content("src/x.c", DECOMPILED)
    assert len(found) == 2 and "header says it is decompiler output" in found[0] and "calls like FUN_00401000" in found[1], found
    locals_only = b"".join(b"  int iVar%d = param_%d + local_%x;\n" % (i, i, i) for i in range(10))
    assert "decompiler-style locals" in " ".join(check_tree.problems_for_content("x.c", locals_only))
    assert check_tree.problems_for_content("x.h", b"typedef undefined4 a; undefined4 b; undefined1 c; undefined2 d; undefined e;")


def test_a_table_of_hundreds_of_decompiler_names_is_recognised():
    table = b"Address,FunctionName\n" + b"".join(b"%08x,FUN_%08x\n" % (0x401000 + i * 16, 0x401000 + i * 16) for i in range(150))
    assert check_tree.problems_for_content("tools/x/index.csv", table)
    assert check_tree.problems_for_content("tools/x/index.csv", table[:300]) == []


def test_a_comment_that_labels_an_address_is_not_decompiler_output():
    # our own sources name globals by the address a decompiler would have labelled them with; that is a label, not decompiled code
    comment = b"".join(b"    uint32_t a%d; /* DAT_%08x: a count */\n" % (i, 0x600000 + i * 4) for i in range(60))
    assert check_tree.problems_for_content("src/native/x.h", comment) == []
    assert check_tree.problems_for_content("docs/notes/x.md", DECOMPILED) == []           # prose is not looked at


def test_the_repository_has_no_decompiler_output():
    if not os.path.isdir(os.path.join(ROOT, ".git")) and not os.path.isfile(os.path.join(ROOT, ".git")):
        pytest.skip("not a git checkout")
    proc = subprocess.run([sys.executable, os.path.join(HERE, "check_tree.py")], capture_output=True, text=True)
    assert proc.returncode == 0, proc.stdout + proc.stderr


def test_an_unpacked_archive_with_a_decompiled_file_fails(tmp_path):
    (tmp_path / "pentamoor-1.0-x").mkdir()
    (tmp_path / "pentamoor-1.0-x" / "ok.c").write_bytes(b"int main(void) { return 0; }\n")
    (tmp_path / "pentamoor-1.0-x" / "dump.c").write_bytes(DECOMPILED)
    proc = subprocess.run([sys.executable, os.path.join(HERE, "check_tree.py"), "--root", str(tmp_path)], capture_output=True, text=True)
    assert proc.returncode == 1 and "dump.c" in proc.stdout and "ok.c" not in proc.stdout
